  insert into public.messages (id, workspace_id, user_id, story_id, body, created_at) values
    ('877f796e-2602-5ad9-a74b-180ae3799497', '46d3cf9b-db36-57d2-abe4-14ec584a2711', '7230ec45-53e7-5344-a34e-5ca004d4a0d0', null, 'Okay team, SE lab project is locked: campus lost & found. First stories are in Trace, LF-1 is sign-in.', now() - interval '47808 minutes'),
    ('4968fd48-b11f-5799-a8c4-a1d68f03394d', '46d3cf9b-db36-57d2-abe4-14ec584a2711', '0c63c6b7-9418-5cd7-aecd-4e238ccc92d2', null, 'I''ll take reporting and search, I''ve done forms before', now() - interval '47664 minutes'),
    ('d3019b16-38c9-5fd4-a806-be052ac11d79', '46d3cf9b-db36-57d2-abe4-14ec584a2711', '09d253fd-633f-5fda-ab03-e8b722b0534f', null, 'I can do photos and the item pages', now() - interval '47592 minutes'),
    ('cc69cf00-85db-5236-aa16-2e06f8acf1ff', '46d3cf9b-db36-57d2-abe4-14ec584a2711', '23797133-4b1e-5902-a5de-edd981f4faa7', null, 'I''ll do notifications then', now() - interval '47520 minutes'),
    ('27f98ece-74e2-5eed-adb6-82d487782970', '46d3cf9b-db36-57d2-abe4-14ec584a2711', '7230ec45-53e7-5344-a34e-5ca004d4a0d0', null, 'Supabase or Firebase? Leaning Supabase, we need joins to match lost vs found items', now() - interval '46512 minutes'),
    ('a19000ab-37a0-5078-ade7-aa251e243895', '46d3cf9b-db36-57d2-abe4-14ec584a2711', '0c63c6b7-9418-5cd7-aecd-4e238ccc92d2', null, '+1, the Firebase rules in our prototype were a mess', now() - interval '46440 minutes'),
    ('f215a599-2c24-5d98-af63-ff97d064826f', '46d3cf9b-db36-57d2-abe4-14ec584a2711', '7230ec45-53e7-5344-a34e-5ca004d4a0d0', null, '/decide Use Supabase instead of Firebase. We need SQL joins for matching and row-level security per user.', now() - interval '46368 minutes'),
    ('77d6e33b-c119-5d11-ade3-53c29efba12e', '46d3cf9b-db36-57d2-abe4-14ec584a2711', '7230ec45-53e7-5344-a34e-5ca004d4a0d0', null, 'Should sign-in be college email only?', now() - interval '45216 minutes'),
    ('a16c5cf3-1c9e-5133-abf5-2f662b00f240', '46d3cf9b-db36-57d2-abe4-14ec584a2711', '09d253fd-633f-5fda-ab03-e8b722b0534f', null, 'yes, the security office asked for that when we met them', now() - interval '45144 minutes'),
    ('b9a40009-b736-5094-a10a-b9421a8ea572', '46d3cf9b-db36-57d2-abe4-14ec584a2711', '09d253fd-633f-5fda-ab03-e8b722b0534f', null, 'photos from phones are like 6 MB each. compressing to webp at 1280px, comes out ~200 KB', now() - interval '35280 minutes'),
    ('a382480d-e234-5023-ae46-21ab4ad41a27', '46d3cf9b-db36-57d2-abe4-14ec584a2711', '0c63c6b7-9418-5cd7-aecd-4e238ccc92d2', null, 'nice, that keeps us inside the free storage too', now() - interval '35208 minutes'),
    ('dfa73ce8-06fd-5c32-a5f9-255a88002c60', '46d3cf9b-db36-57d2-abe4-14ec584a2711', '0c63c6b7-9418-5cd7-aecd-4e238ccc92d2', null, 'search is live, try typing “botle” 😄', now() - interval '26784 minutes'),
    ('f9089872-8071-5d28-a4f9-5c7ad820cb80', '46d3cf9b-db36-57d2-abe4-14ec584a2711', '7230ec45-53e7-5344-a34e-5ca004d4a0d0', null, 'trigrams ftw', now() - interval '26712 minutes'),
    ('ace8f31b-e6f1-5dbf-a236-29f5669d6ea7', '46d3cf9b-db36-57d2-abe4-14ec584a2711', '23797133-4b1e-5902-a5de-edd981f4faa7', null, 'for match alerts I think push is best, nobody reads college email', now() - interval '19296 minutes'),
    ('b19e6381-78a7-5bf8-a8e6-d62f4be9b31d', '46d3cf9b-db36-57d2-abe4-14ec584a2711', '7230ec45-53e7-5344-a34e-5ca004d4a0d0', null, 'push needs a service worker + FCM setup, that''s a lot before the demo', now() - interval '17712 minutes'),
    ('588f8ca4-9c05-5cdb-afc1-ffa1ebf790d0', '46d3cf9b-db36-57d2-abe4-14ec584a2711', '23797133-4b1e-5902-a5de-edd981f4faa7', null, 'hmm ok let me check', now() - interval '17640 minutes'),
    ('cd6cd5ff-47d9-5d4e-a9f8-96b86a6745d8', '46d3cf9b-db36-57d2-abe4-14ec584a2711', '7230ec45-53e7-5344-a34e-5ca004d4a0d0', null, 'going with email alerts for v1, logged it as a decision', now() - interval '13248 minutes'),
    ('e8758de8-6e28-5a83-aa52-5e5482c485e0', '46d3cf9b-db36-57d2-abe4-14ec584a2711', '09d253fd-633f-5fda-ab03-e8b722b0534f', null, 'claim dialog done, adding the wrong-answer limit now', now() - interval '4464 minutes'),
    ('ca53fd3e-9950-5a88-ac03-fbc698578b67', '46d3cf9b-db36-57d2-abe4-14ec584a2711', '0c63c6b7-9418-5cd7-aecd-4e238ccc92d2', null, '@Kabir any update on push? that task is still in todo', now() - interval '7488 minutes'),
    ('0daebaa5-b401-5a0e-a4c3-810723aeae86', '46d3cf9b-db36-57d2-abe4-14ec584a2711', '23797133-4b1e-5902-a5de-edd981f4faa7', null, 'sorry, CN assignment week. will pick it up this weekend', now() - interval '6336 minutes'),
    ('da701c66-b0fe-57d8-a155-cbb0dc3fc612', '46d3cf9b-db36-57d2-abe4-14ec584a2711', '7230ec45-53e7-5344-a34e-5ca004d4a0d0', null, 'Mentor review on Friday. Let''s finish the filters and close the claim flow before that', now() - interval '3024 minutes'),
    ('d84ca7f8-97cb-5d8b-a022-91c438e396fb', '46d3cf9b-db36-57d2-abe4-14ec584a2711', '09d253fd-633f-5fda-ab03-e8b722b0534f', null, 'Kabir raised a dispute on my alert template commit. fair, we paired on it in the lab', now() - interval '1728 minutes');
  insert into public.decisions (id, workspace_id, number, title, rationale, alternatives, story_id, message_id, supersedes, decided_by, created_at) values
    ('f4ca8312-3d0b-58c9-a9e1-9835837de16f', '46d3cf9b-db36-57d2-abe4-14ec584a2711', 1, 'Use Supabase instead of Firebase', 'We need SQL joins to match lost and found items, and row-level security so students only edit their own posts. Firebase rules got messy in the prototype.', 'Firebase (the team already knew it); Express + MySQL (more to host and secure)', null, 'f215a599-2c24-5d98-af63-ff97d064826f', null, '7230ec45-53e7-5344-a34e-5ca004d4a0d0', now() - interval '46368 minutes'),
    ('cdfe3dcd-11bc-52ec-aef5-209667ca2147', '46d3cf9b-db36-57d2-abe4-14ec584a2711', 2, 'Only @nmims.edu.in emails can sign in', 'Keeps the board campus-only and gives the security office someone to contact about each post. Guest access can come later.', 'Any Google account; roll-number login', '1d613feb-1c8c-56d8-adb1-d50e0cc30da9', null, null, '7230ec45-53e7-5344-a34e-5ca004d4a0d0', now() - interval '45072 minutes'),
    ('35377b53-a200-5878-a11f-a5dfd4dbc31f', '46d3cf9b-db36-57d2-abe4-14ec584a2711', 3, 'Compress photos to WebP at 1280 px', 'Phone photos are 4–8 MB. WebP at 1280 px is about 200 KB and still shows labels and stickers clearly, which keeps us inside the free 1 GB storage.', 'Store originals; resize on the server', '43082e40-bf7b-53d9-a26e-3ec3e8e59da9', null, null, '09d253fd-633f-5fda-ab03-e8b722b0534f', now() - interval '35136 minutes'),
    ('0ed44016-818c-51bc-ae18-b38261a5053d', '46d3cf9b-db36-57d2-abe4-14ec584a2711', 4, 'Fuzzy search with Postgres trigrams, not Algolia', 'Typos like “botle” must still match. pg_trgm does that inside the database for free; Algolia''s free tier caps records and adds a second service to run.', 'Algolia; plain ILIKE matching', '51184755-50a2-5c55-a630-a105fc4947cb', null, null, '0c63c6b7-9418-5cd7-aecd-4e238ccc92d2', now() - interval '27360 minutes'),
    ('58d18233-afa2-5c4c-a55a-1160f796542a', '46d3cf9b-db36-57d2-abe4-14ec584a2711', 5, 'Hash secret answers like passwords', 'Finders write the question and owners type the answer. Storing answers hashed means nobody can read them, even if the database leaks.', 'Plain text; encrypt with an app key', 'eb8360af-8b9f-5fb6-a9fc-c28bb24d2e3f', null, null, '7230ec45-53e7-5344-a34e-5ca004d4a0d0', now() - interval '20160 minutes'),
    ('1c5dcca6-22c5-59ae-a8a3-41a0981a072e', '46d3cf9b-db36-57d2-abe4-14ec584a2711', 6, 'Send push notifications for matches', 'Students check their phones, not email. Push notifications reach them fastest when a matching item is posted.', 'Email alerts; SMS', '9da0829a-3a3d-5012-a2a0-f2ab73cd131e', null, null, '23797133-4b1e-5902-a5de-edd981f4faa7', now() - interval '19152 minutes'),
    ('b88287b3-3121-5d1a-a0b6-7c03b8dc3967', '46d3cf9b-db36-57d2-abe4-14ec584a2711', 7, 'Email only for match alerts in v1', 'Push notifications need a service worker and Firebase Cloud Messaging setup we don''t have time for before the demo. Email alerts for matches are enough for v1.', 'Push notifications (Kabir''s plan); in-app badge only', '9da0829a-3a3d-5012-a2a0-f2ab73cd131e', null, null, '7230ec45-53e7-5344-a34e-5ca004d4a0d0', now() - interval '13248 minutes');
  insert into public.disputes (id, workspace_id, kind, item_id, subject, raised_by, note, status, resolution, created_at, resolved_at) values ('7f36ff5e-1dfc-522d-a96c-661008e10f56', '46d3cf9b-db36-57d2-abe4-14ec584a2711', 'commit', '4af481c6-1eff-5c0b-aae6-1c54441a8694', '09d253fd-633f-5fda-ab03-e8b722b0534f', '23797133-4b1e-5902-a5de-edd981f4faa7', 'We paired on this in the lab. I wrote the email copy and the subject lines; Meera pushed it.', 'open', null, now() - interval '4320 minutes', null);
  insert into public.disputes (id, workspace_id, kind, item_id, subject, raised_by, note, status, resolution, created_at, resolved_at) values ('f298fff8-d9ad-58a5-a603-7dc03662fc26', '46d3cf9b-db36-57d2-abe4-14ec584a2711', 'task', '4b170f8d-c935-54ca-a2e2-2ccc9e6a0cca', '23797133-4b1e-5902-a5de-edd981f4faa7', '0c63c6b7-9418-5cd7-aecd-4e238ccc92d2', 'The list of drop-off points came from the security office sheet that I collected. Kabir turned it into the migration.', 'resolved', 'Agreed: Isha gathered the data, Kabir wrote the migration.', now() - interval '8640 minutes', now() - interval '8340 minutes');
  insert into public.sync_state (workspace_id, synced_at) values ('46d3cf9b-db36-57d2-abe4-14ec584a2711', now() - interval '30 minutes');
