  insert into public.decisions (id, workspace_id, number, title, rationale, alternatives, story_id, message_id, supersedes, decided_by, created_at) values
    ('bd1ccf78-30f7-5b11-a19f-912d87b5100c', '1bd4c421-9c5c-59de-adb1-4234c881e26a', 1, 'Ratings are 1 to 5 stars, no comments', 'Comments turned into arguments in the pilot. Stars are quick to give after a meal and easy to average.', 'Thumbs up/down; free-text reviews', null, null, null, '61b94a0e-9d59-50e0-a5d5-4419231e1fd5', now() - interval '36000 minutes'),
    ('18b8e5ac-3cca-5ed6-aaf6-08f66d5c2ce5', '1bd4c421-9c5c-59de-adb1-4234c881e26a', 2, 'Complaints never store the student''s name', 'Students told us they won''t complain if mess staff can trace it back. We store only the hostel block.', 'Store names but hide them in the UI', null, null, null, '61b94a0e-9d59-50e0-a5d5-4419231e1fd5', now() - interval '28800 minutes');
