  insert into public.stories (id, workspace_id, number, title, narrative, acceptance, priority, created_by, created_at) values
    ('60aecba0-7bef-59b9-a99d-29d602370b14', '095e4d20-2bc4-587f-ad73-47db7041b8ae', 1, 'Book a lab slot', 'As a student, I want to book a free lab slot, so that I don''t wait outside a full lab.', 'Given a free slot, when I book it, then it shows as mine and others can''t book it.', 'must', '0e79f92e-aca4-503e-a124-0bf60a5587d6', now() - interval '44640 minutes'),
    ('da72e18b-2ab9-53a7-ae21-74629e66b8d9', '095e4d20-2bc4-587f-ad73-47db7041b8ae', 4, 'Cancel or swap a slot', 'As a student, I want to cancel or swap my slot, so that someone else can use it.', 'Given my booking, when I cancel it up to an hour before, then the slot frees up.', 'must', '1838f3e0-c865-5a60-a8d6-85c945031823', now() - interval '44064 minutes'),
    ('60ebe815-2a1d-5fa4-ae9b-ccf3874f16b9', '095e4d20-2bc4-587f-ad73-47db7041b8ae', 7, 'Lab in-charge approval', 'As a lab in-charge, I want to approve bookings for the project lab, so that equipment isn''t overbooked.', 'Given a project-lab booking, when I approve it, then the student is notified.', 'should', '0e79f92e-aca4-503e-a124-0bf60a5587d6', now() - interval '43488 minutes'),
    ('9eeb8f15-f5da-5ae0-a857-10004b8d739f', '095e4d20-2bc4-587f-ad73-47db7041b8ae', 9, 'Slot reminders', 'As a student, I want a reminder before my slot, so that I don''t miss it.', 'Given a booking, when it''s 30 minutes away, then I get a reminder.', 'should', '9ca911bc-c83f-52da-af2c-28940a1dfad1', now() - interval '42912 minutes'),
    ('75faca32-b369-5f66-a497-26da4ae0ce9f', '095e4d20-2bc4-587f-ad73-47db7041b8ae', 10, 'Sign in with SAP ID', 'As a student, I want to sign in with my SAP ID, so that bookings are tied to me.', 'Given a valid SAP ID, when I sign in, then I see my bookings.', 'must', '0e79f92e-aca4-503e-a124-0bf60a5587d6', now() - interval '42336 minutes'),
    ('6cfffb2f-6c5f-5a20-a561-50b4668d7ad2', '095e4d20-2bc4-587f-ad73-47db7041b8ae', 12, 'Usage report for the HOD', 'As the HOD, I want monthly lab usage, so that I can plan lab hours.', 'Given a month of bookings, when I open the report, then I see usage per lab.', 'could', 'e413e606-1727-5349-ac9a-87b51ac9ba81', now() - interval '41760 minutes');
