  insert into public.stories (id, workspace_id, number, title, narrative, acceptance, priority, created_by, created_at) values
    ('335e97ea-fcea-5355-a7cb-dffed0d6914f', '9befad83-c7ed-5fbd-acb0-6ec8efe67c09', 1, 'Publish an event', 'As a club lead, I want to publish an event with a poster, so that students find it in one place.', 'Given a title, date, venue and poster, when I publish, then the event shows on the home feed.', 'must', '4e900e81-5d5a-580e-a95e-416b8a2ff0e4', now() - interval '44640 minutes'),
    ('ff03ceb3-0673-5278-a3c9-c4fc4ff2b410', '9befad83-c7ed-5fbd-acb0-6ec8efe67c09', 4, 'Register for an event', 'As a student, I want to register in one tap, so that I don''t fill a new Google Form every time.', 'Given I''m signed in, when I tap Register, then I''m on the list and get a confirmation.', 'must', '4c4ed75c-7ac8-571f-a17f-4674b27c7176', now() - interval '44064 minutes'),
    ('b4e8ebca-9b60-5147-a4c3-57509edc84cb', '9befad83-c7ed-5fbd-acb0-6ec8efe67c09', 7, 'QR check-in', 'As a volunteer, I want to scan a QR code at the door, so that attendance is recorded.', 'Given a registered student''s QR, when I scan it, then they are marked present once.', 'should', '4e900e81-5d5a-580e-a95e-416b8a2ff0e4', now() - interval '43488 minutes'),
    ('5c05dd5b-58d8-51d2-a24f-036735c75073', '9befad83-c7ed-5fbd-acb0-6ec8efe67c09', 10, 'Club pages', 'As a student, I want a page per club with its past events, so that I can decide what to join.', 'Given a club, when I open its page, then I see its leads and past events.', 'should', '1ed59f0a-397e-55d6-adf1-24c4b389cd86', now() - interval '42912 minutes'),
    ('5679b50b-09cc-5ebe-a48e-5f9cea6c96ae', '9befad83-c7ed-5fbd-acb0-6ec8efe67c09', 12, 'Sign in for club leads', 'As a club lead, I want my own login, so that only I can publish for my club.', 'Given I''m a lead, when I sign in, then I can publish only for my club.', 'must', '4e900e81-5d5a-580e-a95e-416b8a2ff0e4', now() - interval '42336 minutes'),
    ('5b30b8fe-2a90-5bf9-a729-1f5cce08406c', '9befad83-c7ed-5fbd-acb0-6ec8efe67c09', 14, 'Attendance certificates', 'As a student, I want a certificate after attending, so that I can add it to my CV.', 'Given I attended, when the event ends, then I can download a PDF certificate.', 'could', '565c934f-245d-549a-a317-88ab47cd023e', now() - interval '41760 minutes');
