    ('a045f15c-6170-5042-a525-c2e2a31fd50c', '9befad83-c7ed-5fbd-acb0-6ec8efe67c09', '565c934f-245d-549a-a317-88ab47cd023e', null, 'who''s doing club pages? it''s still unassigned in todo', now() - interval '5760 minutes');
  insert into public.decisions (id, workspace_id, number, title, rationale, alternatives, story_id, message_id, supersedes, decided_by, created_at) values
    ('22f8f9f5-ad8e-580a-a16d-88ef61da42fd', '9befad83-c7ed-5fbd-acb0-6ec8efe67c09', 1, 'Use Google Forms for event registration', 'Clubs already use Google Forms for registration; embedding the form is the fastest way to ship.', 'Build registration in the app', 'ff03ceb3-0673-5278-a3c9-c4fc4ff2b410', null, null, '1ed59f0a-397e-55d6-adf1-24c4b389cd86', now() - interval '34560 minutes'),
    ('9046a838-4146-5f86-a57d-691a53b655ca', '9befad83-c7ed-5fbd-acb0-6ec8efe67c09', 2, 'Build registration in the app, no Google Forms', 'Google Forms registration can''t do one-tap sign-up or QR check-in, and students hate refilling forms for every event.', 'Keep embedding Google Forms', 'ff03ceb3-0673-5278-a3c9-c4fc4ff2b410', null, null, '4e900e81-5d5a-580e-a95e-416b8a2ff0e4', now() - interval '23040 minutes'),
    ('cdd53d27-c530-5585-a1b6-80b8cd4c7e9c', '9befad83-c7ed-5fbd-acb0-6ec8efe67c09', 3, 'One QR code per registration, not per student', 'A per-registration code can''t be reused at another event, so attendance can''t be faked.', 'One QR per student ID', 'b4e8ebca-9b60-5147-a4c3-57509edc84cb', null, null, '4c4ed75c-7ac8-571f-a17f-4674b27c7176', now() - interval '12960 minutes');
  insert into public.disputes (id, workspace_id, kind, item_id, subject, raised_by, note, status, resolution, created_at, resolved_at) values ('a78335ad-e168-54ad-ae02-2d512a712f0f', '9befad83-c7ed-5fbd-acb0-6ec8efe67c09', 'commit', 'b0a51b2b-ef1b-5925-a3fd-e5c6ba40bf54', '4e900e81-5d5a-580e-a95e-416b8a2ff0e4', '1ed59f0a-397e-55d6-adf1-24c4b389cd86', 'Most of this is my forms-embed code moved over. I''d like co-credit.', 'open', null, now() - interval '7200 minutes', null);
  insert into public.disputes (id, workspace_id, kind, item_id, subject, raised_by, note, status, resolution, created_at, resolved_at) values ('f248c8af-6a58-539e-a7f1-30905a82db3e', '9befad83-c7ed-5fbd-acb0-6ec8efe67c09', 'task', '39ccd80f-cfe1-5387-a7e8-4010c5623e6b', '4c4ed75c-7ac8-571f-a17f-4674b27c7176', '565c934f-245d-549a-a317-88ab47cd023e', 'I designed the QR flow and tested it at the club fair; Ishaan only merged it.', 'open', null, now() - interval '4320 minutes', null);
