    ('1d8f8050-4c7d-53ac-a942-2f38f0eaa01d', '46d3cf9b-db36-57d2-abe4-14ec584a2711', 26, 'Map of drop-off points', 'As a student, I want to see drop-off points on a campus map, so that I can find where to collect an item.', 'Given the Found list, when I open the map, then each drop-off point shows its item count.', 'could', '23797133-4b1e-5902-a5de-edd981f4faa7', now() - interval '37440 minutes'),
    ('8de1f86f-9b05-5e25-a227-96eb5535b02c', '46d3cf9b-db36-57d2-abe4-14ec584a2711', 27, 'Weekly digest email', 'As a student, I want a weekly email of unclaimed items, so that I notice things without opening the app.', 'Given unclaimed items this week, when Monday 9 am comes, then subscribers get one digest email.', 'could', '09d253fd-633f-5fda-ab03-e8b722b0534f', now() - interval '37440 minutes');

